xml.Script:
        clCyan      := '00FFFF';
        clTeal      := '008080';
        clBlue      := '0000FF';
        clNavy      := '000080';
        clRed       := 'FF0000';
        clBrown     := '800000';
        clCoral     := 'FF7F50';
        clYellow    := 'FFFF00';
        clOlive     := '808000';
        clOrange    := 'FF6000';
        clLime      := '00FF00';
        clGreen     := '008000';
        clDarkGreen := '006400';
        clFuchsia   := 'FF00FF';
        clPurple    := '800080';
        clPink      := 'FF69B4';

        K  := 0.6;

        C0 := K * ((4 * (11  +  3 * sqrt(69)))^(1/3) - (4 * (-11 +  3 * sqrt(69)))^(1/3) - 1) /  3;
        C1 := K * ((4 * (25  +  3 * sqrt(69)))^(1/3) + (4 * ( 25 -  3 * sqrt(69)))^(1/3) - 5) /  3;
        C2 := K * ((4 * (371 + 33 * sqrt(69)))^(1/3) + (4 * (371 - 33 * sqrt(69)))^(1/3) - 1) / 33;

        // Calcs angle from 2 to 3 while rotating over 1
        function Angle(x1, y1, z1, x2, y2, z2, x3, y3, z3);
        begin
          vx := y1 * z2 - y2 * z1;
          vy := z1 * x2 - z2 * x1;
          vz := x1 * y2 - x2 * y1;
          wx := y1 * z3 - y3 * z1;
          wy := z1 * x3 - z3 * x1;
          wz := x1 * y3 - x3 * y1;
          Result := ArcCos((vx*wx + vy*wy + vz*wz) / (vx^2 + vy^2 + vz^2));
        end;

        A1 := Angle( C1,C0,K, -C1,-C0,K, C0,K,C1);
        A2 := A1 * 2;
        A3 := Angle( C1,C0,K, K,C1,C0, C0,K,C1);

        D := (C1 * C2 - C0 * C2 + K * C2) / sqrt(C1^2 + C0^2 + K^2);
